import{_ as a,o as t,c as s,a2 as l}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"URI プロトコル（lertaro://）","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/uri-protocol.md","filePath":"ja-JP/user-guide/uri-protocol.md","lastUpdated":1787586465000}'),n={name:"ja-JP/user-guide/uri-protocol.md"};function i(o,e,r,d,p,c){return t(),s("div",null,[...e[0]||(e[0]=[l(`<h1 id="uri-プロトコル-lertaro" tabindex="-1">URI プロトコル（lertaro://） <a class="header-anchor" href="#uri-プロトコル-lertaro" aria-label="Permalink to &quot;URI プロトコル（lertaro://）&quot;">​</a></h1><p>Lertaro は初回起動時に、Windows システムにカスタム URI スキーム <strong><code>lertaro://</code></strong> を自動登録します。Web ページのリンク、デスクトップショートカット、自動化スクリプト、サードパーティ製ツールから、特定の検索の呼び出し、設定画面への直接ジャンプ、ファイル送信を直接実行できます。</p><h2 id="_1-プロトコル動作と単一インスタンスルーティング" tabindex="-1">1. プロトコル動作と単一インスタンスルーティング <a class="header-anchor" href="#_1-プロトコル動作と単一インスタンスルーティング" aria-label="Permalink to &quot;1. プロトコル動作と単一インスタンスルーティング&quot;">​</a></h2><ul><li><strong>設定不要で即座に利用可能</strong>：レジストリを手動で変更する必要はありません。起動時に自動的に登録・整合性チェックが行われます。</li><li><strong>単一インスタンスへの転送</strong>：Lertaro がすでにバックグラウンドで起動している場合、<code>lertaro://</code> リンクを開くと起動中のインスタンスへ即座に要求が転送され、二重起動は発生しません。未起動の場合はメインアプリが自動起動して指定されたアクションを実行します。</li></ul><h2 id="_2-uri-ルーティング一覧" tabindex="-1">2. URI ルーティング一覧 <a class="header-anchor" href="#_2-uri-ルーティング一覧" aria-label="Permalink to &quot;2. URI ルーティング一覧&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">URI スキーム形式</th><th style="text-align:left;">動作内容と画面の挙動</th></tr></thead><tbody><tr><td style="text-align:left;"><code>lertaro://</code></td><td style="text-align:left;">クイック検索ウィンドウを表示（<code>Ctrl</code> 2 回連打と同等）。</td></tr><tr><td style="text-align:left;"><code>lertaro://search/[キーワード]</code></td><td style="text-align:left;">クイックウィンドウを表示し、指定した <code>[キーワード]</code> を入力して即座に絞り込み。</td></tr><tr><td style="text-align:left;"><code>lertaro://fullsearch/[キーワード]</code></td><td style="text-align:left;">メイン検索ウィンドウを開き、指定した <code>[キーワード]</code> を入力。</td></tr><tr><td style="text-align:left;"><code>lertaro://settings/page/[セクション]</code></td><td style="text-align:left;">設定画面を開き、指定したトップレベルセクションへ直接切り替え。</td></tr><tr><td style="text-align:left;"><code>lertaro://settings/entry/[ID番号]</code></td><td style="text-align:left;">設定画面を開き、特定の個別設定項目へジャンプしてハイライト表示。</td></tr><tr><td style="text-align:left;"><code>lertaro://localsend</code></td><td style="text-align:left;">LocalSend の空のファイル送信画面を開く。</td></tr><tr><td style="text-align:left;"><code>lertaro://localsend/items/[エンコードされた絶対パス...]</code></td><td style="text-align:left;">LocalSend をファイル送信モードで開き、1 つまたは複数のパスを事前追加。</td></tr><tr><td style="text-align:left;"><code>lertaro://localsend/text/[エンコードされたテキスト]</code></td><td style="text-align:left;">LocalSend をテキスト送信モードで開き、指定したテキストを入力済みにする。</td></tr></tbody></table><h3 id="設定セクション名-セクション" tabindex="-1">設定セクション名 <code>[セクション]</code> <a class="header-anchor" href="#設定セクション名-セクション" aria-label="Permalink to &quot;設定セクション名 \`[セクション]\`&quot;">​</a></h3><p>大文字小文字を区別せず、設定画面のサイドバーに対応しています。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Service      - サービス状態</span></span>
<span class="line"><span>Index        - インデックス設定</span></span>
<span class="line"><span>General      - 一般設定</span></span>
<span class="line"><span>Appearance   - 外観とテーマ</span></span>
<span class="line"><span>Hotkeys      - ホットキー設定</span></span>
<span class="line"><span>Plugins      - プラグイン管理</span></span>
<span class="line"><span>Favorites    - お気に入り</span></span>
<span class="line"><span>History      - 検索履歴</span></span>
<span class="line"><span>QuickPanel   - クイックパネル</span></span>
<span class="line"><span>About        - バージョン情報</span></span></code></pre></div><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><code>lertaro://settings/entry/[ID番号]</code> の番号は、内蔵の <a href="./instant-answers.html#2-キーワード起動機能内蔵プラグイン"><strong>設定検索</strong></a> で動的に生成される内部 ID です。バージョン更新等で変化する可能性があるため、スクリプト等では <code>lertaro://settings/page/[セクション]</code> の使用を推奨します。</p></div><h2 id="_3-localsend-パラメータとエンコード規則" tabindex="-1">3. LocalSend パラメータとエンコード規則 <a class="header-anchor" href="#_3-localsend-パラメータとエンコード規則" aria-label="Permalink to &quot;3. LocalSend パラメータとエンコード規則&quot;">​</a></h2><p>LocalSend の URI を利用する場合、各ファイルパスやテキストは標準的な URL エンコードを行う必要があります（例: <code>:</code> は <code>%3A</code>、<code>\\</code> は <code>%5C</code>、スペースは <code>%20</code>）。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 複数ファイルを指定</span></span>
<span class="line"><span>lertaro://localsend/items/C%3A%5CUsers%5Ctestuser%5CDesktop%5Cdoc.pdf/D%3A%5CShared%5Cphotos</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 送信テキストを指定</span></span>
<span class="line"><span>lertaro://localsend/text/Hello%20from%20Lertaro%21</span></span></code></pre></div><ul><li><strong>セキュリティ要件</strong>：指定するパスはローカルに実在する絶対パスである必要があります。データを含むリンクは端末選択画面を開くだけで、自動的に送信を開始することはありません。</li></ul><h2 id="_4-連携スクリプトと活用例" tabindex="-1">4. 連携スクリプトと活用例 <a class="header-anchor" href="#_4-連携スクリプトと活用例" aria-label="Permalink to &quot;4. 連携スクリプトと活用例&quot;">​</a></h2><h3 id="markdown-やナレッジベースでのリンク" tabindex="-1">Markdown やナレッジベースでのリンク <a class="header-anchor" href="#markdown-やナレッジベースでのリンク" aria-label="Permalink to &quot;Markdown やナレッジベースでのリンク&quot;">​</a></h3><p>Obsidian や Notion、社内ドキュメントに直接リンクを埋め込めます。</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">Lertaro の外観設定を開く</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">lertaro://settings/page/Appearance</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">プロジェクト財務諸表を検索</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">lertaro://search/財務諸表%202026</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h3 id="デスクトップショートカットやバッチ" tabindex="-1">デスクトップショートカットやバッチ <a class="header-anchor" href="#デスクトップショートカットやバッチ" aria-label="Permalink to &quot;デスクトップショートカットやバッチ&quot;">​</a></h3><p>デスクトップで右クリックしてショートカットを作成し、リンク先に以下を指定します。</p><div class="language-cmd vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cmd</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">lertaro://fullsearch/D:\\Projects\\</span></span></code></pre></div><p>PowerShell からの実行例：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Start-Process</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;lertaro://settings/page/General&quot;</span></span></code></pre></div><h2 id="_5-安全性と未知のルーティングの保護" tabindex="-1">5. 安全性と未知のルーティングの保護 <a class="header-anchor" href="#_5-安全性と未知のルーティングの保護" aria-label="Permalink to &quot;5. 安全性と未知のルーティングの保護&quot;">​</a></h2><ul><li><strong>安全な無視とロギング</strong>：外部の Web サイトやスクリプトから呼び出される可能性があるため、Lertaro はすべての URI パラメータを厳格に検証します。構文エラーや存在しないルーティングは静かに無視され、ログにのみ記録されます。予期せぬ動作やクラッシュを引き起こすことはありません。</li></ul>`,25)])])}const k=a(n,[["render",i]]);export{g as __pageData,k as default};
